        echo '<div class="mp-panel"><form method="get"><input type="hidden" name="page" value="mabna-bale-participants"><div class="mp-filter"><div><label>جست‌وجوی سریع</label><input type="search" name="s" value="'.esc_attr($search).'" placeholder="نام، شماره، شناسه بله، نتیجه یا رویداد"></div><div><label>وضعیت</label><select name="status"><option value="">همه وضعیت‌ها</option><option value="completed" '.selected($status,'completed',false).'>تکمیل‌شده</option><option value="active" '.selected($status,'active',false).'>در حال انجام</option></select></div><div><label>تیپ شخصیتی</label><input name="result" value="'.esc_attr($result).'" maxlength="4" placeholder="مثلاً ENFJ"></div><div><label>رویداد</label><select name="event_id"><option value="0">همه رویدادها</option>';foreach($events_list as $ev)echo '<option value="'.(int)$ev['id'].'" '.selected($event_id,(int)$ev['id'],false).'>'.esc_html($ev['title']).'</option>';echo '</select></div><div><label>از تاریخ ورود</label><input type="date" name="date_from" value="'.esc_attr($from).'" ></div><div><label>تا تاریخ ورود</label><input type="date" name="date_to" value="'.esc_attr($to).'" ></div><button class="button button-primary">اعمال فیلتر</button></div><div class="mp-actions"><a class="button" href="'.esc_url($clear_url).'">پاک‌کردن فیلترها</a><a class="button" href="'.esc_url($export_url).'">دانلود گزارش CSV</a><span class="mp-muted">'.number_format_i18n($total).' رکورد مطابق فیلتر</span></div></form></div>';
