        if(!$rows)echo '<tr><td colspan="9" class="mp-empty">شرکت‌کننده‌ای با این مشخصات پیدا نشد.</td></tr>';foreach($rows as $r){$name=trim((string)$r['first_name'].' '.(string)$r['last_name']);$nonce=wp_create_nonce('mabna_bale_delete_participant_'.(int)$r['id']);$pill=$r['status']==='completed'?'<span class="mp-pill ok">تکمیل‌شده</span>':'<span class="mp-pill live">در حال انجام</span>';echo '<tr id="mabna-participant-'.(int)$r['id'].'"><td><span class="mp-name">'.esc_html($name?:'بدون نام').'</span><span class="mp-muted">جلسه #'.(int)$r['id'].'</span></td><td>'.esc_html($r['phone']?:'—').'</td><td><code>'.esc_html($r['chat_id']).'</code></td><td>'.($r['result_key']?'<span class="mp-type">'.esc_html($r['result_key']).'</span>':'<span class="mp-muted">هنوز مشخص نشده</span>').'</td><td>'.$pill.'</td><td><span class="mp-muted">'.esc_html($r['created_at']?:'—').'</span></td><td><span class="mp-muted">'.esc_html($r['completed_at']?:'—').'</span></td><td>'.esc_html($r['event_title']?:'—').'</td><td><button type="button" class="button button-small button-link-delete mabna-delete-participant" data-session-id="'.(int)$r['id'].'" data-nonce="'.esc_attr($nonce).'">حذف سوابق</button></td></tr>';}
