    public function delete_participant(): void {
        if ( ! current_user_can( 'manage_options' ) ) wp_die( 'دسترسی غیرمجاز.' );
        $session_id = absint( $_GET['session_id'] ?? 0 );
        check_admin_referer( 'mabna_bale_delete_participant_' . $session_id );
        if ( $session_id ) {
            global $wpdb;
            $tables = Mabna_Bale_Challenge_DB::tables();
            $wpdb->delete( $tables['results'], [ 'session_id' => $session_id ], [ '%d' ] );
            $wpdb->delete( $tables['referrals'], [ 'referrer_session_id' => $session_id ], [ '%d' ] );
            $wpdb->delete( $tables['sessions'], [ 'id' => $session_id ], [ '%d' ] );
            Mabna_Bale_Challenge_DB::log( 'participant_deleted', '', 0, [ 'session_id' => $session_id ] );
        }
        wp_safe_redirect( admin_url( 'admin.php?page=mabna-bale-participants&deleted=1' ) );
        exit;
    }
    public function ajax_delete_participant(): void {
        if ( ! current_user_can( 'manage_options' ) ) wp_send_json_error( [ 'message' => 'دسترسی غیرمجاز.' ], 403 );
        $session_id = absint( $_POST['session_id'] ?? 0 );
        check_ajax_referer( 'mabna_bale_delete_participant_' . $session_id, 'nonce' );
        if ( ! $session_id ) wp_send_json_error( [ 'message' => 'شناسهٔ شرکت‌کننده نامعتبر است.' ], 400 );
        global $wpdb;
        $tables = Mabna_Bale_Challenge_DB::tables();
        $wpdb->delete( $tables['results'], [ 'session_id' => $session_id ], [ '%d' ] );
        $wpdb->delete( $tables['referrals'], [ 'referrer_session_id' => $session_id ], [ '%d' ] );
        $deleted = $wpdb->delete( $tables['sessions'], [ 'id' => $session_id ], [ '%d' ] );
        if ( false === $deleted ) wp_send_json_error( [ 'message' => 'حذف در پایگاه داده انجام نشد.' ], 500 );
        Mabna_Bale_Challenge_DB::log( 'participant_deleted', '', 0, [ 'session_id' => $session_id, 'transport' => 'ajax' ] );
        wp_send_json_success( [ 'session_id' => $session_id ] );
    }
    public function dashboard(): void {
        $this->header( 'کنترل پنل ربات بله مبنا' );
        global $wpdb;
        $info = get_option( 'mabna_bale_webhook_info', [] ); $logs = (array) get_option( 'mabna_bale_logs', [] ); $identity = (array) get_option( 'mabna_bale_bot_identity', [] );
        $total = (int) $wpdb->get_var( "SELECT COUNT(DISTINCT user_id) FROM {$wpdb->usermeta} WHERE meta_key='mabna_bale_chat_id' AND meta_value<>''" );
        $new_7 = (int) $wpdb->get_var( $wpdb->prepare( "SELECT COUNT(*) FROM {$wpdb->usermeta} WHERE meta_key='mabna_bale_connected_at' AND meta_value >= %s", date( 'Y-m-d H:i:s', current_time( 'timestamp' ) - 7 * DAY_IN_SECONDS ) ) );
        $new_30 = (int) $wpdb->get_var( $wpdb->prepare( "SELECT COUNT(*) FROM {$wpdb->usermeta} WHERE meta_key='mabna_bale_connected_at' AND meta_value >= %s", date( 'Y-m-d H:i:s', current_time( 'timestamp' ) - 30 * DAY_IN_SECONDS ) ) );
        $errors = 0; foreach ( $logs as $log ) if ( str_contains( (string) ( $log['event'] ?? '' ), 'error' ) ) $errors++;
        echo '<p>مدیریت اتصال ربات بله به کاربران سایت و تنظیمات آینده بات.</p><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:14px;max-width:1000px;margin:18px 0">';
