        echo '</div><table class="widefat striped" style="max-width:900px"><tbody>';
        echo '<tr><th>وضعیت توکن</th><td>' . ( get_option( 'mabna_bale_token' ) ? '<span style="color:green">وارد شده</span>' : '<span style="color:#a00">وارد نشده</span>' ) . '</td></tr>';
        echo '<tr><th>آدرس Webhook</th><td><code>' . esc_html( mabna_bale_webhook_url() ) . '</code></td></tr>';
        echo '<tr><th>وضعیت Webhook</th><td>' . esc_html( (string) ( $info['url'] ?? 'بررسی نشده' ) ) . '</td></tr>';
        echo '<tr><th>ربات فعال</th><td>' . esc_html( ( $identity['first_name'] ?? '' ) . ( ! empty( $identity['username'] ) ? ' (@' . $identity['username'] . ')' : '' ) ?: 'شناسایی نشده' ) . '</td></tr>';
        echo '<tr><th>تعداد رویدادهای ثبت‌شده</th><td>' . count( $logs ) . '</td></tr></tbody></table>';
        $recent = array_reverse( array_slice( $logs, -8 ) ); echo '<h2>آخرین فعالیت‌ها</h2><table class="widefat striped" style="max-width:900px"><thead><tr><th>زمان</th><th>رویداد</th><th>جزئیات</th></tr></thead><tbody>'; foreach ( $recent as $log ) echo '<tr><td>' . esc_html( $log['time'] ?? '' ) . '</td><td>' . esc_html( $log['event'] ?? '' ) . '</td><td><code>' . esc_html( wp_json_encode( $log['data'] ?? [], JSON_UNESCAPED_UNICODE ) ) . '</code></td></tr>'; echo '</tbody></table>';
        echo '<p><a class="button button-primary" href="' . esc_url( admin_url( 'admin.php?page=mabna-bale-settings' ) ) . '">رفتن به تنظیمات ربات</a></p>';
        $this->footer();
    }
