    public function save_settings(): void {
        if ( ! current_user_can( 'manage_options' ) ) wp_die( 'دسترسی غیرمجاز.' ); check_admin_referer( 'mabna_bale_save_settings' );
        $old_token = (string) get_option( 'mabna_bale_token', '' );
        $new_token = sanitize_text_field( wp_unslash( $_POST['mabna_bale_token'] ?? '' ) );
        if ( $old_token !== '' && $new_token !== '' && ! hash_equals( $old_token, $new_token ) ) {
            ( new Mabna_Bale_API( $old_token ) )->delete_webhook();
            mabna_bale_log( 'bot_token_changed', [ 'old_fingerprint' => substr( hash( 'sha256', $old_token ), 0, 12 ), 'new_fingerprint' => substr( hash( 'sha256', $new_token ), 0, 12 ) ] );
            delete_option( 'mabna_bale_webhook_info' );
        }
        update_option( 'mabna_bale_token', $new_token );
        $allowed = [];
        foreach ( (array) ( $_POST['mabna_bale_phone_priority'] ?? [] ) as $raw_key ) {
            $candidate = sanitize_text_field( wp_unslash( $raw_key ) );
            foreach ( $this->phone_keys as $known_key ) if ( strtolower( $candidate ) === strtolower( $known_key ) ) $candidate = $known_key;
            if ( $candidate !== '' ) $allowed[] = $candidate;
        }
        update_option( 'mabna_bale_phone_priority', array_values( array_unique( $allowed ) ) ?: $this->phone_keys );
        $primary = sanitize_key( $_POST['mabna_bale_primary_phone_meta'] ?? 'kerasno-phone' ); update_option( 'mabna_bale_primary_phone_meta', in_array( $primary, $this->phone_keys, true ) ? $primary : 'kerasno-phone' );
        update_option( 'mabna_bale_channel', sanitize_text_field( wp_unslash( $_POST['mabna_bale_channel'] ?? '' ) ) ); update_option( 'mabna_bale_product_category', sanitize_title( wp_unslash( $_POST['mabna_bale_product_category'] ?? 'nevisandegi' ) ) );
        foreach ( $this->messages as $key => $field ) update_option( 'mabna_bale_msg_' . $key, sanitize_textarea_field( wp_unslash( $_POST['mabna_bale_msg_' . $key] ?? $field['default'] ) ) );
        wp_safe_redirect( admin_url( 'admin.php?page=mabna-bale-settings&saved=1' ) ); exit;
    }
    public function webhook_action(): void {
        if ( ! current_user_can( 'manage_options' ) ) wp_die( 'دسترسی غیرمجاز.' ); check_admin_referer( 'mabna_bale_webhook' ); $op = sanitize_key( $_POST['operation'] ?? 'info' ); $result = $op === 'set' ? mabna_bale_api()->set_webhook( mabna_bale_webhook_url() ) : ( $op === 'delete' ? mabna_bale_api()->delete_webhook() : mabna_bale_api()->webhook_info() ); $ok = ! empty( $result['ok'] ); if ( $ok ) { update_option( 'mabna_bale_webhook_info', $result['result'] ?? $result ); if ( $op === 'set' ) { $me = mabna_bale_api()->get_me(); if ( ! empty( $me['ok'] ) ) update_option( 'mabna_bale_bot_identity', $me['result'] ); } } $msg = $ok ? ( $op === 'set' ? 'Webhook با موفقیت فعال شد.' : ( $op === 'delete' ? 'Webhook با موفقیت غیرفعال شد.' : 'وضعیت Webhook دریافت شد.' ) ) : ( $result['description'] ?? 'خطا در ارتباط با API بله.' ); wp_safe_redirect( admin_url( 'admin.php?page=mabna-bale-settings&webhook=' . ( $ok ? '1' : '0' ) . '&message=' . rawurlencode( $msg ) ) ); exit;
    }
    public function users(): void {
        if ( ! current_user_can( 'manage_options' ) ) wp_die( 'دسترسی غیرمجاز.' );
        global $wpdb;
        $users_table = $wpdb->users;
        $meta_table  = $wpdb->usermeta;
        $sessions    = Mabna_Bale_Challenge_DB::tables()['sessions'];
        $referrals   = Mabna_Bale_Challenge_DB::tables()['referrals'];

        $search = sanitize_text_field( wp_unslash( $_GET['s'] ?? '' ) );
        $status = sanitize_key( $_GET['status'] ?? '' );
        $result = strtoupper( sanitize_text_field( wp_unslash( $_GET['result'] ?? '' ) ) );
        $from   = sanitize_text_field( wp_unslash( $_GET['date_from'] ?? '' ) );
        $to     = sanitize_text_field( wp_unslash( $_GET['date_to'] ?? '' ) );
        $view_session = absint( $_GET['view_referrals'] ?? 0 );
        $paged  = max( 1, absint( $_GET['paged'] ?? 1 ) );
        $per_page = min( 100, max( 10, absint( $_GET['per_page'] ?? 25 ) ) );
        $offset = ( $paged - 1 ) * $per_page;

        $latest_session = "LEFT JOIN {$sessions} s ON s.id=(SELECT ss.id FROM {$sessions} ss WHERE ss.user_id=u.ID ORDER BY ss.id DESC LIMIT 1)";
        $joins = "JOIN {$meta_table} chat ON chat.user_id=u.ID AND chat.meta_key='mabna_bale_chat_id' AND chat.meta_value<>'' LEFT JOIN {$meta_table} phone ON phone.user_id=u.ID AND phone.meta_key='mabna_bale_phone' LEFT JOIN {$meta_table} connected ON connected.user_id=u.ID AND connected.meta_key='mabna_bale_connected_at' {$latest_session} LEFT JOIN (SELECT referrer_session_id,COUNT(*) AS referral_count FROM {$referrals} GROUP BY referrer_session_id) rc ON rc.referrer_session_id=s.id";
        $where = [ '1=1' ]; $args = [];
        if ( $search !== '' ) { $like='%'.$wpdb->esc_like($search).'%'; $where[]='(u.display_name LIKE %s OR u.user_email LIKE %s OR phone.meta_value LIKE %s OR chat.meta_value LIKE %s OR s.result_key LIKE %s)'; array_push($args,$like,$like,$like,$like,$like); }
        if ( in_array($status,['active','completed'],true) ) { $where[]='s.status=%s'; $args[]=$status; }
        if ( preg_match('/^[A-Z]{4}$/',$result) ) { $where[]='s.result_key=%s'; $args[]=$result; }
        if ( preg_match('/^\\d{4}-\\d{2}-\\d{2}$/',$from) ) { $where[]='DATE(connected.meta_value)>=%s'; $args[]=$from; }
        if ( preg_match('/^\\d{4}-\\d{2}-\\d{2}$/',$to) ) { $where[]='DATE(connected.meta_value)<=%s'; $args[]=$to; }
        $where_sql=implode(' AND ',$where);
        $base="SELECT SQL_CALC_FOUND_ROWS s.id AS session_id,u.ID,u.display_name,u.user_email,chat.meta_value AS bale_id,phone.meta_value AS phone,connected.meta_value AS connected_at,s.status,s.result_key,s.completed_at,s.referral_code,COALESCE(rc.referral_count,0) AS referral_count FROM {$users_table} u {$joins} WHERE {$where_sql} ORDER BY COALESCE(connected.meta_value,'1970-01-01') DESC,u.ID DESC";
        $is_export = isset($_GET['export']) && $_GET['export']==='csv';
        $sql = $base . ( $is_export ? ' LIMIT 5000' : ' LIMIT %d OFFSET %d' );
        $query_args=$args; if(!$is_export){$query_args[]=$per_page;$query_args[]=$offset;}
        $prepared=$query_args?$wpdb->prepare($sql,$query_args):$sql;
        $rows=$wpdb->get_results($prepared,ARRAY_A);
        $total=(int)$wpdb->get_var('SELECT FOUND_ROWS()');
        if($is_export){
            nocache_headers(); header('Content-Type: text/csv; charset=utf-8'); header('Content-Disposition: attachment; filename=mabna-bale-users-'.gmdate('Y-m-d').'.csv'); echo "\\xEF\\xBB\\xBF"; $out=fopen('php://output','w'); fputcsv($out,['شناسه','نام','ایمیل','شماره همراه','شناسه بله','وضعیت','تیپ شخصیتی','زمان اتصال','زمان تکمیل','تعداد دعوت'],','); foreach($rows as $r) fputcsv($out,[$r['ID'],$r['display_name'],$r['user_email'],$r['phone'],$r['bale_id'],$r['status'],$r['result_key'],$r['connected_at'],$r['completed_at'],$r['referral_count']],','); fclose($out); exit;
        }
        $total_connected=(int)$wpdb->get_var("SELECT COUNT(DISTINCT user_id) FROM {$meta_table} WHERE meta_key='mabna_bale_chat_id' AND meta_value<>''");
        $total_completed=(int)$wpdb->get_var("SELECT COUNT(*) FROM {$sessions} WHERE user_id>0 AND status='completed'");
        $total_active=(int)$wpdb->get_var("SELECT COUNT(*) FROM {$sessions} WHERE user_id>0 AND status='active'");
        $total_referrals=(int)$wpdb->get_var("SELECT COUNT(*) FROM {$referrals}");
        $type_rows=$wpdb->get_results("SELECT result_key,COUNT(*) AS c FROM {$sessions} WHERE user_id>0 AND status='completed' AND result_key<>'' GROUP BY result_key ORDER BY c DESC",ARRAY_A);
        $referral_rows=[]; if($view_session){$referral_rows=$wpdb->get_results($wpdb->prepare("SELECT r.*,rs.first_name,rs.last_name,rs.phone FROM {$referrals} r LEFT JOIN {$sessions} rs ON rs.event_id=r.event_id AND rs.chat_id=r.referred_chat_id WHERE r.referrer_session_id=%d ORDER BY r.created_at DESC",$view_session),ARRAY_A);}
        $export_url=add_query_arg(array_filter(['page'=>'mabna-bale-users','s'=>$search,'status'=>$status,'result'=>$result,'date_from'=>$from,'date_to'=>$to,'export'=>'csv']),admin_url('admin.php'));
        $clear_url=admin_url('admin.php?page=mabna-bale-users');
        $this->header('مرکز مدیریت کاربران ربات بله');
        echo '<style>.mabna-users{font-family:inherit}.mabna-users *{box-sizing:border-box}.mabna-hero{background:linear-gradient(135deg,#172554,#2563eb);color:#fff;border-radius:18px;padding:26px 30px;margin:18px 0 20px;display:flex;justify-content:space-between;align-items:center;gap:20px}.mabna-hero h2{margin:0 0 8px;color:#fff;font-size:24px}.mabna-hero p{margin:0;color:#dbeafe;font-size:14px}.mabna-hero .dashicons{font-size:58px;width:58px;height:58px;opacity:.8}.mabna-stat-grid{display:grid;grid-template-columns:repeat(4,minmax(150px,1fr));gap:14px;margin:0 0 20px}.mabna-stat{background:#fff;border:1px solid #e5e7eb;border-radius:14px;padding:18px;box-shadow:0 3px 12px rgba(15,23,42,.05);position:relative;overflow:hidden}.mabna-stat:after{content:"";position:absolute;bottom:0;right:0;left:0;height:3px;background:var(--c)}.mabna-stat small{display:block;color:#64748b;margin-bottom:8px}.mabna-stat strong{font-size:28px;color:#0f172a}.mabna-stat .dashicons{float:left;color:var(--c);font-size:28px}.mabna-panel{background:#fff;border:1px solid #e5e7eb;border-radius:14px;padding:18px;margin:0 0 18px;box-shadow:0 3px 12px rgba(15,23,42,.04)}.mabna-filter{display:grid;grid-template-columns:2fr repeat(4,1fr) auto;gap:10px;align-items:end}.mabna-filter label{display:block;font-size:12px;font-weight:600;color:#475569;margin-bottom:5px}.mabna-filter input,.mabna-filter select{width:100%;min-height:38px}.mabna-actions{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-top:13px}.mabna-table-wrap{overflow:auto}.mabna-users table{border:0;min-width:1050px}.mabna-users th{background:#f8fafc;color:#334155;font-weight:700;white-space:nowrap}.mabna-users td,.mabna-users th{padding:12px 10px;vertical-align:middle}.mabna-users tbody tr:hover{background:#f8fbff}.mabna-name{font-weight:700;color:#1e293b}.mabna-muted{color:#64748b;font-size:12px;display:block;margin-top:3px}.mabna-pill{display:inline-flex;padding:4px 9px;border-radius:999px;font-size:11px;font-weight:700}.mabna-pill.ok{background:#dcfce7;color:#166534}.mabna-pill.live{background:#dbeafe;color:#1d4ed8}.mabna-pill.none{background:#f1f5f9;color:#64748b}.mabna-type{font-family:monospace;font-weight:700;background:#eef2ff;color:#3730a3;padding:4px 8px;border-radius:6px}.mabna-ref{color:#7c3aed;font-weight:700}.mabna-types{display:flex;gap:8px;flex-wrap:wrap}.mabna-type-card{background:#f8fafc;border:1px solid #e2e8f0;border-radius:9px;padding:8px 11px;min-width:90px}.mabna-type-card b{display:block;font-size:16px;color:#312e81}.mabna-type-card span{font-size:11px;color:#64748b}.mabna-pagination{display:flex;justify-content:space-between;align-items:center;margin-top:16px;gap:12px}.mabna-pagination a,.mabna-pagination strong{display:inline-block;padding:6px 10px;border:1px solid #dbe3ef;border-radius:7px;text-decoration:none}.mabna-pagination strong{background:#2563eb;color:#fff;border-color:#2563eb}.mabna-empty{text-align:center;color:#64748b;padding:40px!important}@media(max-width:900px){.mabna-stat-grid{grid-template-columns:repeat(2,1fr)}.mabna-filter{grid-template-columns:1fr 1fr}.mabna-filter>div:first-child{grid-column:1/-1}}@media(max-width:520px){.mabna-stat-grid{grid-template-columns:1fr}.mabna-filter{grid-template-columns:1fr}.mabna-filter>div:first-child{grid-column:auto}}</style>';
        echo '<div class="mabna-users"><div class="mabna-hero"><div><h2>مرکز مدیریت کاربران ربات بله</h2><p>نمایش اتصال‌ها، وضعیت آزمون، تیپ شخصیتی، دعوت‌ها و گزارش عملکرد کاربران در یک نگاه</p></div><span class="dashicons dashicons-groups"></span></div>';
        echo '<div class="mabna-stat-grid"><div class="mabna-stat" style="--c:#2563eb"><span class="dashicons dashicons-admin-users"></span><small>کاربران متصل</small><strong>'.number_format_i18n($total_connected).'</strong></div><div class="mabna-stat" style="--c:#16a34a"><span class="dashicons dashicons-yes-alt"></span><small>نتیجه تکمیل‌شده</small><strong>'.number_format_i18n($total_completed).'</strong></div><div class="mabna-stat" style="--c:#7c3aed"><span class="dashicons dashicons-update"></span><small>در حال انجام</small><strong>'.number_format_i18n($total_active).'</strong></div><div class="mabna-stat" style="--c:#ea580c"><span class="dashicons dashicons-share"></span><small>دعوت ثبت‌شده</small><strong>'.number_format_i18n($total_referrals).'</strong></div></div>';
        echo '<div class="mabna-panel"><div style="display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap"><h3 style="margin:0">توزیع تیپ‌های شخصیتی</h3><span class="mabna-muted">بر اساس نتایج تکمیل‌شده</span></div><div class="mabna-types" style="margin-top:14px">';
        if($type_rows){foreach($type_rows as $tr)echo '<div class="mabna-type-card"><b>'.esc_html($tr['result_key']).'</b><span>'.number_format_i18n((int)$tr['c']).' نتیجه</span></div>';}else echo '<span class="mabna-muted">هنوز نتیجه‌ای ثبت نشده است.</span>'; echo '</div></div>';
        if($view_session){$back_url=add_query_arg(array_filter(['page'=>'mabna-bale-users','s'=>$search,'status'=>$status,'result'=>$result,'date_from'=>$from,'date_to'=>$to]),admin_url('admin.php'));echo '<div class="mabna-panel" style="border-right:4px solid #7c3aed"><div style="display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap"><div><h3 style="margin:0 0 5px">فهرست دعوت‌های کاربر</h3><span class="mabna-muted">جلسه معرف #'.(int)$view_session.' · '.number_format_i18n(count($referral_rows)).' دعوت ثبت‌شده</span></div><a class="button" href="'.esc_url($back_url).'">بازگشت به فهرست کاربران</a></div><div class="mabna-table-wrap" style="margin-top:14px"><table class="widefat"><thead><tr><th>دعوت‌شده</th><th>شماره همراه</th><th>شناسه چت بله</th><th>کد معرف</th><th>زمان ثبت دعوت</th></tr></thead><tbody>';if($referral_rows){foreach($referral_rows as $rr){$rn=trim((string)$rr['first_name'].' '.(string)$rr['last_name']);echo '<tr><td><strong>'.esc_html($rn?:'کاربر بله').'</strong></td><td>'.esc_html($rr['phone']?:'—').'</td><td><code>'.esc_html($rr['referred_chat_id']).'</code></td><td><code>'.esc_html($rr['referrer_code']).'</code></td><td>'.esc_html($rr['created_at']).'</td></tr>';}}else echo '<tr><td colspan="5" class="mabna-empty">برای این کاربر هنوز دعوتی ثبت نشده است.</td></tr>';echo '</tbody></table></div></div>';}
