        echo '<div class="mabna-panel"><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px"><h3 style="margin:0">فهرست کاربران</h3><span class="mabna-muted">صفحه '.number_format_i18n($paged).' از '.number_format_i18n(max(1,ceil($total/$per_page))).'</span></div><div class="mabna-table-wrap"><table class="widefat"><thead><tr><th>کاربر</th><th>شماره همراه</th><th>شناسه بله</th><th>وضعیت</th><th>نتیجه</th><th>دعوت‌ها</th><th>اتصال</th><th>عملیات</th></tr></thead><tbody>';
