        echo '</tbody></table></div>';
        $pages=max(1,(int)ceil($total/$per_page)); if($pages>1){echo '<div class="mabna-pagination"><span class="mabna-muted">نمایش '.number_format_i18n($offset+1).' تا '.number_format_i18n(min($offset+$per_page,$total)).'</span><div>';for($i=1;$i<=$pages;$i++){if($i===1||$i===$pages||abs($i-$paged)<=2){$url=add_query_arg(array_filter(['page'=>'mabna-bale-users','s'=>$search,'status'=>$status,'result'=>$result,'date_from'=>$from,'date_to'=>$to,'paged'=>$i,'per_page'=>$per_page]),admin_url('admin.php'));echo $i===$paged?'<strong>'.number_format_i18n($i).'</strong> ':'<a href="'.esc_url($url).'">'.number_format_i18n($i).'</a> ';}}echo '</div></div>';}
        echo '</div></div>'; $this->footer();
    }
    public function unlink_user(): void {
        if ( ! current_user_can( 'manage_options' ) ) wp_die( 'دسترسی غیرمجاز.' );
        $user_id = absint( $_GET['user_id'] ?? 0 );
        check_admin_referer( 'mabna_bale_unlink_user_' . $user_id );
        if ( $user_id > 0 ) {
            delete_user_meta( $user_id, 'mabna_bale_chat_id' );
            delete_user_meta( $user_id, 'mabna_bale_phone' );
            delete_user_meta( $user_id, 'mabna_bale_connected_at' );
            mabna_bale_log( 'user_unlinked', [ 'user_id' => $user_id ] );
        }
        wp_safe_redirect( admin_url( 'admin.php?page=mabna-bale-users&unlinked=1' ) ); exit;
    }
    public function events(): void {
        global $wpdb; $table=Mabna_Bale_Challenge_DB::tables()['events']; $events=$wpdb->get_results("SELECT * FROM {$table} ORDER BY id DESC",ARRAY_A); $edit_id=absint($_GET['edit_event']??0); $editing=$edit_id?Mabna_Bale_Challenge_DB::event($edit_id):[]; $questions=mabna_bale_challenge_questions($editing?:[]);
        $message=$editing['message']??"به ماشین زمان نویسندگی مبنا خوش اومدی!\n\nبا پاسخ دادن به ۶ سؤال کوتاه، می‌فهمی آینده‌ات شبیه کدوم نویسنده میشه.\n\nآماده‌ای ببینیم در آینده پشت کدوم میز نویسندگی نشستی؟";
        if ( $editing ) {
        echo '<h2>'.($editing?'ویرایش رویداد':'افزودن رویداد').'</h2><form method="post" enctype="multipart/form-data" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field('mabna_bale_save_event');echo '<input type="hidden" name="action" value="mabna_bale_save_event"><input type="hidden" name="event_id" value="'.(int)$edit_id.'"><table class="form-table"><tr><th>عنوان</th><td><input class="regular-text" name="title" value="'.esc_attr($editing['title']??'آینده‌ات شبیه کدوم نویسنده میشه؟').'" required></td></tr><tr><th>پیام اصلی</th><td><textarea class="large-text" rows="5" name="message" required>'.esc_textarea($message).'</textarea></td></tr>';
        foreach($questions as $i=>$q){$n=$i+1;echo '<tr><th>سؤال '.$n.'</th><td><textarea class="large-text" rows="2" name="q_text['.$i.']" required>'.esc_textarea($q['text']).'</textarea><input class="regular-text" name="q_opt['.$i.'][0]" value="'.esc_attr($q['options'][0]??'گزینه اول').'" required> <input class="regular-text" name="q_opt['.$i.'][1]" value="'.esc_attr($q['options'][1]??'گزینه دوم').'" required></td></tr>';}
        $config=$editing['result_config']??[]; $authors=is_array($config['authors']??null)&&$config['authors']? $config['authors']:mabna_bale_mbti_authors(); $type_images=[]; foreach($authors as $ak=>$av) $type_images[$ak]=(string)($av['image_url']??''); $author_image_fields='<tr><th>تصویر هر تیپ شخصیتی</th><td><p class="description">برای هر تیپ، آدرس تصویر کارت نتیجه را وارد کنید.</p>'; foreach($authors as $ak=>$av) $author_image_fields.='<label style="display:block;margin:5px 0"><code>'.esc_html($ak).'</code> '.esc_html($av['name']??'').' <input class="regular-text mabna-media-url" type="url" name="type_image['.esc_attr($ak).']" value="'.esc_attr($type_images[$ak]).'" placeholder="https://..."><button type="button" class="button mabna-media-button">انتخاب تصویر</button><button type="button" class="button mabna-media-clear">پاک کردن</button></label>'; $author_image_fields.='</td></tr>'; echo '<tr><th>تصویر صفحه اول</th><td><div class="mabna-media-picker"><input class="regular-text mabna-media-url" type="url" name="intro_image_url" value="'.esc_attr($config['intro_image_url']??'').'" placeholder="https://..."><button type="button" class="button mabna-media-button">انتخاب از کتابخانه</button><button type="button" class="button mabna-media-clear">پاک کردن</button></div></td></tr><tr><th>تصویر کارت نتیجه پیش‌فرض</th><td><div class="mabna-media-picker"><input class="regular-text mabna-media-url" type="url" name="result_image_url" value="'.esc_attr($config['image_url']??'').'" placeholder="https://..."><button type="button" class="button mabna-media-button">انتخاب از کتابخانه</button><button type="button" class="button mabna-media-clear">پاک کردن</button></div></td></tr>'.$author_image_fields.'<tr><th>نویسنده‌ها (JSON)</th><td><textarea class="large-text code" rows="5" name="authors_json">'.esc_textarea(wp_json_encode($authors,JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT)).'</textarea><p class="description">هر نویسنده: key, name, image_url, features؛ سه ویژگی اول در کارت استفاده می‌شود.</p></td></tr><tr><th>پیامک اعضای مبنا</th><td><input class="regular-text" name="sms_mabna_pattern" value="'.esc_attr($config['sms_mabna_pattern']??'').'"><p class="description">کد الگوی ملی‌پیامک برای خریداران محصولات دسته نویسندگی.</p></td></tr><tr><th>پیامک غیرعضو مبنا</th><td><input class="regular-text" name="sms_non_mabna_pattern" value="'.esc_attr($config['sms_non_mabna_pattern']??'').'"><p class="description">کد الگوی ملی‌پیامک برای افرادی که خرید معتبر مبنا ندارند.</p></td></tr><tr><th>لینک کلید بله</th><td><input class="regular-text" type="url" name="bale_result_url" value="'.esc_attr($config['bale_result_url']??'').'" placeholder="https://ble.ir/..."></td></tr><tr><th>لینک کلید ایتا</th><td><input class="regular-text" type="url" name="eitaa_result_url" value="'.esc_attr($config['eitaa_result_url']??'').'" placeholder="https://eitaa.com/..."></td></tr><tr><th>لینک پست آموزشی قدیمی</th><td><input class="regular-text" type="url" name="result_url" value="'.esc_attr($config['post_url']??'').'" placeholder="https://..."></td></tr><tr><th>شروع</th><td><input type="datetime-local" name="start" value="'.esc_attr($editing['start']??'').'"></td></tr><tr><th>پایان</th><td><input type="datetime-local" name="end" value="'.esc_attr($editing['end']??'').'"></td></tr><tr><th>فعال</th><td><label><input type="checkbox" name="active" value="1" '.(!empty($editing['is_active'])?'checked':'').'> فعال باشد</label><p class="description">به‌صورت پیش‌فرض خاموش است؛ خالی‌بودن زمان‌ها یعنی نامحدود.</p></td></tr></table>';submit_button($editing?'ذخیره تغییرات':'ذخیره رویداد');if($editing)echo ' <a class="button" href="'.esc_url(admin_url('admin.php?page=mabna-bale-events')).'">انصراف</a>';echo '</form><hr><h2>رویدادها و چالش‌ها</h2><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:18px;max-width:1100px">';
        }
        foreach($events as $e){$id=(int)$e['id'];$edit=admin_url('admin.php?page=mabna-bale-events&edit_event='.$id);$toggle=wp_nonce_url(admin_url('admin-post.php?action=mabna_bale_toggle_event&event_id='.$id),'mabna_bale_toggle_event_'.$id);$send=wp_nonce_url(admin_url('admin-post.php?action=mabna_bale_send_event&event_id='.$id),'mabna_bale_send_event_'.$id);echo '<div style="background:#fff;border:1px solid #dcdcde;border-radius:10px;padding:20px"><h3><a href="'.esc_url($edit).'">'.esc_html($e['title']).'</a></h3><p><strong>وضعیت:</strong> '.(!empty($e['is_active'])?'<span style="color:#16803c">فعال</span>':'<span style="color:#a00">غیرفعال</span>').'</p><p><strong>بازه:</strong> '.esc_html(($e['start_at']?:'نامحدود').' تا '.($e['end_at']?:'نامحدود')).'</p><p><a class="button button-primary" href="'.esc_url($edit).'">تنظیمات</a> <a class="button" href="'.esc_url($toggle).'">'.(!empty($e['is_active'])?'غیرفعال کردن':'فعال کردن').'</a> <a class="button" href="'.esc_url($send).'">ارسال برای اعضا</a></p></div>';}
        echo '</div>'; $this->media_picker_script(); $this->footer();
    }
    public function save_event(): void { if(!current_user_can('manage_options'))wp_die('دسترسی غیرمجاز.');check_admin_referer('mabna_bale_save_event');$texts=(array)($_POST['q_text']??[]);$opts=(array)($_POST['q_opt']??[]);$questions=[];for($i=0;$i<6;$i++)$questions[]=['text'=>sanitize_textarea_field(wp_unslash($texts[$i]??'')),'options'=>[sanitize_text_field(wp_unslash($opts[$i][0]??'')),sanitize_text_field(wp_unslash($opts[$i][1]??''))]];$decode=function($key){$value=json_decode(wp_unslash($_POST[$key]??'[]'),true);return is_array($value)?$value:[];};$authors=$decode('authors_json');if(!$authors)$authors=mabna_bale_mbti_authors();foreach($authors as $ak=>&$av){if(isset($_POST['type_image'][$ak]))$av['image_url']=esc_url_raw(wp_unslash($_POST['type_image'][$ak]));}unset($av);$event=['title'=>sanitize_text_field(wp_unslash($_POST['title']??'')),'message'=>sanitize_textarea_field(wp_unslash($_POST['message']??'')),'questions'=>$questions,'result_config'=>['intro_image_url'=>esc_url_raw(wp_unslash($_POST['intro_image_url']??'')),'image_url'=>esc_url_raw(wp_unslash($_POST['result_image_url']??'')),'post_url'=>esc_url_raw(wp_unslash($_POST['result_url']??'')),'bale_result_url'=>esc_url_raw(wp_unslash($_POST['bale_result_url']??'')),'eitaa_result_url'=>esc_url_raw(wp_unslash($_POST['eitaa_result_url']??'')),'authors'=>$authors,'score_map'=>mabna_bale_mbti_score_map(),'sms_mabna_pattern'=>sanitize_text_field(wp_unslash($_POST['sms_mabna_pattern']??'')),'sms_non_mabna_pattern'=>sanitize_text_field(wp_unslash($_POST['sms_non_mabna_pattern']??''))],'start'=>sanitize_text_field(wp_unslash($_POST['start']??'')),'end'=>sanitize_text_field(wp_unslash($_POST['end']??'')),'active'=>!empty($_POST['active'])];update_option('mabna_bale_sms_pattern',sanitize_text_field(wp_unslash($_POST['sms_pattern']??'')));$id=Mabna_Bale_Challenge_DB::upsert_event($event,absint($_POST['event_id']??0));wp_safe_redirect(admin_url('admin.php?page=mabna-bale-events&edit_event='.$id.'&saved=1'));exit;}
    public function send_event(): void {if(!current_user_can('manage_options'))wp_die('دسترسی غیرمجاز.');$id=absint($_GET['event_id']??0);check_admin_referer('mabna_bale_send_event_'.$id);$event=Mabna_Bale_Challenge_DB::event($id);if(!$event||empty($event['is_active'])||!mabna_bale_event_in_window(['active'=>$event['is_active'],'start'=>$event['start_at'],'end'=>$event['end_at']]))wp_die('رویداد غیرفعال است یا خارج از بازه زمانی قرار دارد.');global $wpdb;$ids=$wpdb->get_col("SELECT DISTINCT user_id FROM {$wpdb->usermeta} WHERE meta_key='mabna_bale_chat_id' AND meta_value<>''");$sent=0;foreach($ids as $uid){$r=mabna_bale_api()->send_message((string)get_user_meta((int)$uid,'mabna_bale_chat_id',true),$event['message'],['reply_markup'=>mabna_bale_event_markup($id)]);if(!empty($r['ok']))$sent++;}Mabna_Bale_Challenge_DB::log('event_broadcast','',0,['event_id'=>$id,'sent'=>$sent,'total'=>count($ids)]);wp_safe_redirect(admin_url('admin.php?page=mabna-bale-events&sent=1'));exit;}
    public function toggle_event(): void {if(!current_user_can('manage_options'))wp_die('دسترسی غیرمجاز.');$id=absint($_GET['event_id']??0);check_admin_referer('mabna_bale_toggle_event_'.$id);global $wpdb;$t=Mabna_Bale_Challenge_DB::tables()['events'];$wpdb->query($wpdb->prepare("UPDATE {$t} SET is_active=IF(is_active=1,0,1),updated_at=%s WHERE id=%d",current_time('mysql'),$id));wp_safe_redirect(admin_url('admin.php?page=mabna-bale-events&saved=1'));exit;}
    public function logs(): void { global $wpdb; $this->header( 'لاگ فعالیت‌های ربات بله' ); $table=Mabna_Bale_Challenge_DB::tables()['logs']; $logs=$wpdb->get_results("SELECT * FROM {$table} ORDER BY id DESC LIMIT 500",ARRAY_A); echo '<table class="widefat striped"><thead><tr><th>زمان</th><th>رویداد</th><th>شناسه بله</th><th>کاربر</th><th>جزئیات</th></tr></thead><tbody>'; foreach($logs as $log)echo '<tr><td>'.esc_html($log['created_at']).'</td><td>'.esc_html($log['event_type']).'</td><td>'.esc_html($log['chat_id']).'</td><td>'.(int)$log['user_id'].'</td><td><code>'.esc_html((string)$log['payload']).'</code></td></tr>';echo '</tbody></table>';$this->footer(); }
